public final class ResourceClassOperationSpec extends ContractNodeSpec{public static final String VARIANT="RESOURCE_OPERATION";private final ComponentRef sourceComponent;private final TriggerSpec activation;private final ConditionExpr condition;private final CostSpec cost;private final int actionTimeTurns;private final ResourceOperationSpec operation;private final boolean hudVisible;private final int hudOrder;public ResourceClassOperationSpec(StableId id,DisplayName name,ComponentRef source,TriggerSpec activation,ConditionExpr condition,CostSpec cost,int turns,ResourceOperationSpec operation,boolean visible,int order){super(id,name,NodeKind.OPERATION,VARIANT,ImplementationState.IMPLEMENTED);if(activation==null||condition==null||cost==null||operation==null||turns<1||order<0)throw new IllegalArgumentException("resource class operation fields required");sourceComponent=source;this.activation=activation;this.condition=condition;this.cost=cost;actionTimeTurns=turns;this.operation=operation;hudVisible=visible;hudOrder=order;}public ComponentRef sourceComponent(){return sourceComponent;}public TriggerSpec activation(){return activation;}public ConditionExpr condition(){return condition;}public CostSpec cost(){return cost;}public int actionTimeTurns(){return actionTimeTurns;}public ResourceOperationSpec operation(){return operation;}public boolean hudVisible(){return hudVisible;}public int hudOrder(){return hudOrder;}@Override public ResourceClassOperationSpec withIdentity(StableId id){return new ResourceClassOperationSpec(id,displayName(),sourceComponent,activation,condition,cost,actionTimeTurns,operation,hudVisible,hudOrder);}@Override public ResourceClassOperationSpec withDisplayName(DisplayName name){return new ResourceClassOperationSpec(id(),name,sourceComponent,activation,condition,cost,actionTimeTurns,operation,hudVisible,hudOrder);}}
